const plugin: Plugin = {
  describe() {
    return {
      id: "default",
      name: "轻快完成",
      version: "1.0.0",
      initialState: "open",
      states: {
        open: { label: "未完成", category: "open" },
        done: { label: "已完成", category: "done" },
      },
      actions: [
        { id: "complete", label: "完成", from: ["open"] },
        { id: "reopen", label: "重新打开", from: ["done"] },
      ],
      fields: [
        { key: "reflection", label: "复盘", type: "text", required: true }
      ],
    };
  },
  decide(data) {
    const { task, action, input } = data;
    const def = this.describe();

    const validAction = def.actions.find((a) => a.id === action && a.from.includes(task.state));
    if (!validAction) {
      return { kind: "reject", message: "当前状态不能执行此操作" };
    }

    if (action === "complete") {
      const val = input["reflection"];
      const trimmed = typeof val === "string" ? val.trim() : "";
      const len = Array.from(trimmed).length;
      if (len === 0) {
        return { kind: "input-required", fields: def.fields };
      }
      if (len > 5000) {
        return { kind: "reject", message: "复盘字数超出5000限制" };
      }
      return {
        kind: "commit",
        state: "done",
        fields: { ...task.fields, reflection: trimmed },
      };
    }

    if (action === "reopen") {
      return {
        kind: "commit",
        state: "open",
        fields: { ...task.fields },
      };
    }

    return { kind: "reject", message: "未知动作" };
  }
};

export default plugin;

export default {
  title: "轻快完成",
  fields: ["reflection"]
};

