import type { Plugin } from "./contract.js";

const definition = {
  id: "default",
  name: "轻快完成",
  version: "1.0.0",
  initialState: "open",
  states: {
    open: { label: "未完成", category: "open" as const },
    done: { label: "已完成", category: "done" as const },
  },
  actions: [
    { id: "complete", label: "完成", from: ["open"] },
    { id: "reopen", label: "重新打开", from: ["done"] },
  ],
  fields: [
    {
      key: "reflection",
      label: "复盘",
      type: "text" as const,
      required: true,
    },
  ],
};

const plugin: Plugin = {
  describe: () => definition,
  decide: (data) => {
    const { task, action, input } = data;
    const allowedAction = definition.actions.find(
      (a) => a.id === action && a.from.includes(task.state)
    );

    if (!allowedAction) {
      return { kind: "reject", message: "当前状态不能执行此操作" };
    }

    if (action === "complete") {
      let reflection = input.reflection;
      if (typeof reflection === "string") {
        reflection = reflection.trim();
      }

      if (!reflection) {
        return {
          kind: "input-required",
          fields: definition.fields,
        };
      }

      const len = [...reflection].length;
      if (len < 1 || len > 5000) {
        return { kind: "reject", message: "复盘字数须在1到5000之间" };
      }

      return {
        kind: "commit",
        state: "done",
        fields: {
          ...task.fields,
          reflection,
        },
      };
    }

    if (action === "reopen") {
      return {
        kind: "commit",
        state: "open",
        fields: {
          ...task.fields,
        },
      };
    }

    return { kind: "reject", message: "未知动作" };
  },
};

export default plugin;

export default {
  title: "轻快完成",
  fields: ["reflection"]
};

