      }

      const len = [...reflection].length;
      if (len < 1 || len > 5000) {
        return { kind: "reject", message: "复盘字数须在1到5000之间" };
      }

      return {
        kind: "commit",
        state: "done",
        fields: {
          ...task.fields,
          reflection,
        },
      };
    }

