        kind: "commit",
        state: "open",
        fields: {
          ...task.fields,
          count: newCount.toString(),
        },
      };
    }

    if (action === "reopen") {
      return {
        kind: "commit",
        state: "open",
        fields: {
          ...task.fields,
        },
      };
    }

    return { kind: "reject", message: "未知动作" };
  },
};

export default plugin;

